1. Matemáticas: verificar si un número es primo


Ver/ocultar código
def es_primo(n):
    if n &lt; 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

casos = {7: True, 15: False, 2: True, 1: False, 97: True}
for n, esperado in casos.items():
    resultado = es_primo(n)
    assert resultado == esperado, f"Falló en n={n}"
    print(f"es_primo({n}) = {resultado}  [correcto]")

1. Matemáticas: verificar si un número es primo


Ver/ocultar código
es_primo &lt;- function(n) {
  if (n &lt; 2) return(FALSE)
  if (n &lt; 4) return(TRUE)
  for (i in 2:floor(sqrt(n))) {
    if (n %% i == 0) return(FALSE)
  }
  return(TRUE)
}

casos &lt;- list(`7` = TRUE, `15` = FALSE, `2` = TRUE, `97` = TRUE)
for (n in names(casos)) {
  resultado &lt;- es_primo(as.numeric(n))
  stopifnot(resultado == casos[[n]])
  cat(sprintf("es_primo(%s) = %s  [correcto]\n", n, resultado))
}

3. Resolver una ecuación cuadrática


Ver/ocultar código
resolver_cuadratica &lt;- function(a, b, c) {
  disc &lt;- b^2 - 4*a*c
  x1 &lt;- (-b + sqrt(disc)) / (2*a)
  x2 &lt;- (-b - sqrt(disc)) / (2*a)
  return(c(x1, x2))
}

a &lt;- 1; b &lt;- -3; c &lt;- 2  # x^2 - 3x + 2 = 0 -&gt; raíces 1 y 2
raices &lt;- resolver_cuadratica(a, b, c)

for (x in raices) {
  valor &lt;- a*x^2 + b*x + c
  stopifnot(abs(valor) &lt; 1e-9)
}

cat("Raíces:", raices, "\n")
cat("Ambas raíces satisfacen la ecuación (verificado)\n")
